    ElementType data;
    struct node *next;
} node;
typedef node* List;
```

### 初始化

```c
void initList(List *L) {
    List p = *L;
    while(p && p->next) p = p->next;
    if(!p) {
        *L = (node*)malloc(sizeof(node));
        p = *L;
        scanf("%d", &p->data);
        p->next = NULL;
