```
1
3
6
2
```

## Code

### C

```c
#include <stdio.h>
#include <math.h>
int main() {
  int N, a, b, count = 0;
  scanf("%d", &N);
  for(int i = 1; i <= N; i++) {
    scanf("%d", &a);
    while(a > 0) {
      b = a % 2;
      a /= 2;
      if(b == 1) {
        count++;
      }
    }
    printf("%d\n", count);
    count = 0;
  }
}
```

### C++

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
	int N, temp, count = 0;
	cin >> N;
	for(int i = 1; i <= N; i++) {
		cin >> temp;
		while(temp > 0) {
			if(temp % 2 == 1) count++;
			temp /= 2;
		}
		cout << count << endl;
		count = 0;
	}
}
