## C++ STL

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    while (cin >> n && n != 0)
    {
        array<array<int, 200>, 200> a;
        array<int, 100> line {} , row {};  // 0: count, 1-100: mark
        for(int i = 1; i <= n; i++)
        {
            for(int j = 1; j <= n; j++)
            {
                cin >> a[i][j];
            }
        }
        for(int i = 1; i <= n; i++)
        {
            int count = 0;
            for(int j = 1; j <= n; j++)
            {
                if(a[i][j] == 1) count++;
            }
            if(count % 2 == 1)
            {
                line[i] = 1;
                line[0]++;
            }
        }
        for(int i = 1, j = 1; j <= n; j++, i = 1)
        {
            int count = 0;
            for(; i <= n; i++)
            {
                if(a[i][j] == 1) count++;
            }
            if(count % 2 == 1)
            {
                row[j] = 1;
                row[0]++;
            }
        }
        if(row[0] == 1 && line[0] == 1)
        {
            int x, y;
            for(int i = 1; i <= n; i++)
            {
                if(line[i] == 1) {x = i; break;}
            }
            for(int i = 1; i <= n; i++)
            {
                if(row[i] == 1) {y = i; break;}
            }
            cout << "Change bit ("<< x << "," << y <<")" << endl;
        } else if(row[0] == 0 && line[0] == 0) cout << "OK" << endl;
        else cout << "Corrupt" << endl;
    }
}
