## Code

### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0), cout.tie(0);
	vector<char> s1, s2;
	array<int, 300> a {};
	string str;
	for (int i = 1; i <= 2; i++) {
		cin >> str;
		for (auto j : str) {
			if (i == 1) s1.insert(s1.begin(), j);
			if (i == 2) s2.insert(s2.begin(), j);
		}
	}
	int j = 0;
	for (; j < (int)s1.size() && j < (int)s2.size(); j++) a[j] = s1[j]-'0' + (s2[j]-'0');
	for (; j < (int)s1.size(); j++) a[j] = s1[j]-'0';
	for (; j < (int)s2.size(); j++) a[j] = s2[j]-'0';
	int count = j;
	for (int i = 0; i < j; i++) {
		a[i + 1] += a[i] / 10;
		if(i+1 == j && a[i] / 10 > 0) count++;
		a[i] = a[i] % 10;
	}
	int flag = 0;
	if(count - 1 > 0) {
		for(int i = count-1; i > -1; i--) {
			if(flag == 0) {
				if(a[i] != 0) {
					cout << a[i];
					flag = 1;
				}
			} else if(flag == 1) cout << a[i];
		}
	} else {
		for(int i = count-1; i > -1; i--) cout << a[i];
	}
}
```

