        cin >> n >> m;
        createTree(n);
        for(int j = 1; j <= m; ++j) {
            cin >> typ;
            if(typ == 1) {
                cin >> x >> y;
                swap(x, y, n);
            } else {
                cin >> x;
                findLeftestChildAndPrint(x);
            }

        }
    }
}
