2 3
-1 -1
-1 -1
```

## 样例输出

```cpp
2
```

## 分析

1. 它的输入部分非常符合层序输出的序列，所以，我们可以搭建一个队列，然后将数据输入。
2. 获得深度——实质上用`max(getDepth(T->l)+1, getDepth(T->r)+1);`就可以了。

## Code

```cpp
#include <bits/stdc++.h>
using namespace std;
struct BinTree {
	int data;
	BinTree *l, *r;
};

int max(int a, int b) {
	return a > b? a: b;
}

int getDepth(BinTree *T) {
	if(T) return max(getDepth(T->l)+1, getDepth(T->r)+1);
	else return 0;
}

int main() {
	BinTree *T = (BinTree*)malloc(sizeof(BinTree));
	queue<BinTree **> Q;
	int data;
	scanf("%d", &data);
	T->data = 1;
	Q.push(&T);
	Q.push(&(*(Q.front()))->l);
	Q.push(&(*(Q.front()))->r);
	Q.pop();
	while(!Q.empty()) {
		scanf("%d", &data);
		if(data == -1) {
			*(Q.front()) = NULL;
			Q.pop();
		} else {
			*(Q.front()) = (BinTree*)malloc(sizeof(BinTree));
			(*(Q.front()))->data = data;
			Q.push(&(*(Q.front()))->l);
			Q.push(&(*(Q.front()))->r);
			Q.pop();
		}
	}
	printf("%d", getDepth(T));
}
```

