5/6
```

## 思路


## Code

### C++ STL

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
	int n, c;
	pair<int, int> num, res(0, 0);
	string a;
	cin >> n;
	for(int i = 1; i <= n; i++) {
		getline(cin, a, '/');
		num.first = atoi(a.c_str());
		getline(cin, a);
		num.second = atoi(a.c_str());
		if(res.first == 0 && res.second == 0) {
			res.first = num.first;
			res.second = num.second;
		} else {
			res.first *= num.second;
			c = res.second;
			res.second *= num.second;
			num.first *= c;
			num.second *= c;
			res.first += num.first;
			if(res.first > res.second) {
				if(res.first % res.second == 0) {
					c = res.second;
					res.first /= c;
					res.second /= c;
				} 
			} else if(res.first == res.second) {
					res.first = 1;
					res.second = 1;
			} else if(res.first < res.second) {
				if(res.second % res.first == 0) {
					c = res.first;
					res.first /= c;
					res.second /= c;
				} 
			}
		}
	}
	int flag = 1;
	while(flag) {
		for(int i = 2; i < 10; i++) {
			if(res.first % i == 0 && res.second % i == 0) {
				flag = 1;
				res.first /= i;
				res.second /= i;
				goto out;
			}
		}
		flag = 0;
		out:;
	}
	if(res.first != res.second && res.second != 1) cout << res.first << "/" << res.second;
	else if(res.second == 1) cout << res.first;
}
