3
```

## 思路

使用取模运算和整除运算分别得到百位、十位和个位数。

## Code

### C

```c
#include <stdio.h>
#include <math.h>
int main() {
    int a;
    scanf("%d", &a);
    printf("%d\n", a/100);
    printf("%d\n", (a%100)/10);
    printf("%d\n", a%10);
}
```

### C++

```cpp
#include <iostream>
#include <bits/stdc++.h>
using namespace std;
int main() {
	array<int, 3> a;
	int num;
	cin >> num;
	for(int i = 2; num > 0; i--) {
		a[i] = num % 10;
		num /= 10;
	}
	for(auto i: a) {
		cout << i << endl;
	}
}
```

