using namespace std;

int main() {
    int k, m, n, sum = 0, tmp;
    cin >> k;
    for(int i = 1; i <= k; i++) {
        cin >> m >> n;
        array<array<int, 100>, 100> a;
        for(int j = 0; j < m; j++) {
            for(int k = 0; k < n; k++) {
                cin >> a[j][k];
            }
        }
        for(int j = 0; j < m; j++) {
            for(int k = 0; k < n; k++) {
                if(j == 0 || k == 0 || j == m-1 || k == n-1) sum += a[j][k];
            }
        }
        cout << sum << endl;
        sum = 0;
    }
}
```

### C

### 解法一：直接计算

