    for(int i = 1; i <= k; i++) {
        scanf("%d %d", &m, &n);
        for(int j = 0; j < m; j++) {
            for(int k = 0; k < n; k++) {
                    scanf("%d", &tmp);
                    if(j == 0 || k == 0 || j == m-1 || k == n-1) sum += tmp;
