#include <bits/stdc++.h>
using namespace std;

int main() {
	int k, m, n, sum = 0, tmp;
	cin >> k;
	for(int i = 1; i <= k; i++) {
		cin >> m >> n;
		for(int j = 0; j < m; j++) {
			for(int k = 0; k < n; k++) {
					cin >> tmp;
					if(j == 0 || k == 0 || j == m-1 || k == n-1) sum += tmp;
			}
		}
		cout << sum << endl;
		sum = 0;
	}
}
```

