node *init() {
    node *L = (node*)malloc(sizeof(node));
    L->next = NULL;
    return L;
}

int main() {
    node *L = init(), *p = L, *q, *k; int n, b;
    scanf("%d", &n);
    for(int i = 1; i <= n; i++) {
        p->next = (node*)malloc(sizeof(node));
        p = p->next;
        p->next = NULL;
        scanf("%d", &p->data);
