## Code

### C

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
typedef struct node {
	char data[9999999];
	struct node *next;
} Node;
void addNode(Node **head, char data[]) {
	Node *p = (Node*)malloc(sizeof(Node)), *q = *head;
	strcpy((*p).data, data);
	if(*head != 0) {
		*head = p;
		(*p).next = q;
	} else {
		*head = p;
        (**head).next = NULL;
	}
}
void readNode(Node **head) {
	Node *last = *head;
	while(last != 0) {
		printf("%s\n", last->data);
		last = last->next;
	}
}
int main() {
	Node *head = NULL;
	static char data[9999999];
	static int old, grade;
	while(gets(data), strcmp(data, "end")) {
        addNode(&head, data);
	}
	readNode(&head);
}
```

### C++

```cpp
#include <bits/stdc++.h>
#include <iostream>
using namespace std;
