	string str;
	stack<string> S;
	do {
		getline(cin, str);
		if(str.find("end") == -1) S.push(str);
	} while(str.find("end") == -1);
	while(!S.empty()) {
		cout << S.top() << endl;
		S.pop();
	}
}
