            fa[i] = i;
        }
    }
    ```
2. 查询`find`
    ```cpp
    int find(int i) {
        if(i == fa[i]) return i;
        else {
            fa[i] = find(fa[i]);
            return fa[i];
        }
    }
    ```
3. 合并`unionn`
    ```cpp
    void union1(int a, int b) {
	     int afa = find(a), bfa = find(b);
         fa[afa] = bfa;
    }
    ```
4. 更新`update`（这个是我写题时想到的）
    ```cpp
    int update(int i) {
        if(i == fa[i]) return i;
        else {
            fa[i] = find(fa[i]);
            return fa[i];
        }
    }
    ```
5. 最后的数据整理工作（如统计最大的人数等）
